        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_stores_produce_consistent_cache() {
        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                std::thread::spawn(move || {
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        // After all concurrent writes, the entry must be internally consistent:
        // metadata.size_bytes must match the actual content length.
        let entry = store
            .load("http:test", "shared-template")
            .unwrap()
            .unwrap();
        let content = store.read_content(&entry).unwrap();
        assert_eq!(
            entry.metadata.size_bytes,
            content.len() as u64,
            "metadata size {} doesn't match content length {}",
            entry.metadata.size_bytes,
            content.len()
        );
    }

    #[test]
    fn atomic_write_not_visible_during_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "atomic-test", "initial content", 3600)
            .unwrap();

        // Overwrite with new content
        store
            .store("http:test", "atomic-test", "updated content", 3600)
            .unwrap();

        // Verify the entry is consistent after overwrite
        let entry = store.load("http:test", "atomic-test").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "updated content");
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }
}

